function mapEntityEdge(record) {
  const rawConfidence = getRecordValue(record, "confidence");
  const confidence = Array.isArray(rawConfidence) && rawConfidence.length === 3 ? [rawConfidence[0] ?? 0, rawConfidence[1] ?? 0, rawConfidence[2] ?? 0] : null;
  const rawEpistemicHistory = getRecordValue(record, "epistemic_history");
  let epistemicHistory = null;
  if (rawEpistemicHistory) {
    if (typeof rawEpistemicHistory === "string") {
      try {
        const parsed = JSON.parse(rawEpistemicHistory);
        epistemicHistory = parsed.map((t) => ({
          ...t,
          timestamp: new Date(t.timestamp)
        }));
      } catch {
        epistemicHistory = null;
      }
    } else if (Array.isArray(rawEpistemicHistory)) {
      epistemicHistory = rawEpistemicHistory.map((t) => ({
        ...t,
        timestamp: t.timestamp instanceof Date ? t.timestamp : new Date(t.timestamp)
      }));
    }
  }
  const rawBirthScore = getRecordValue(record, "birth_score");
  let birthScore = null;
  if (rawBirthScore) {
    if (typeof rawBirthScore === "string") {
      try {
        birthScore = JSON.parse(rawBirthScore);
      } catch {
        birthScore = null;
      }
    } else {
      birthScore = rawBirthScore;
    }
  }
  const rawConditions = getRecordValue(record, "conditions");
  let conditions = null;
  if (rawConditions) {
    if (typeof rawConditions === "string") {
      try {
        conditions = JSON.parse(rawConditions);
      } catch {
        conditions = null;
      }
    } else if (Array.isArray(rawConditions)) {
      conditions = rawConditions;
    }
  }
  const rawInterpretations = getRecordValue(record, "interpretations");
  let interpretations = null;
  if (rawInterpretations) {
    if (typeof rawInterpretations === "string") {
      try {
        const parsed = JSON.parse(rawInterpretations);
        interpretations = parsed.map((interp) => ({
          ...interp,
          computed_at: new Date(interp.computed_at)
        }));
      } catch {
        interpretations = null;
      }
    } else if (Array.isArray(rawInterpretations)) {
      interpretations = rawInterpretations.map((interp) => ({
        ...interp,
        computed_at: interp.computed_at instanceof Date ? interp.computed_at : new Date(interp.computed_at)
      }));
    }
  }
  return {
    uuid: getRecordValue(record, "uuid") ?? "",
    group_id: getRecordValue(record, "group_id") ?? "",
    source_node_uuid: getRecordValue(record, "source_node_uuid") ?? "",
    target_node_uuid: getRecordValue(record, "target_node_uuid") ?? "",
    created_at: parseDateValue(getRecordValue(record, "created_at")) ?? new Date,
    name: getRecordValue(record, "name") ?? "",
    fact: getRecordValue(record, "fact") ?? "",
    fact_embedding: getRecordValue(record, "fact_embedding") ?? null,
    episodes: getRecordValue(record, "episodes") ?? [],
    expired_at: parseDateValue(getRecordValue(record, "expired_at")),
    valid_at: parseDateValue(getRecordValue(record, "valid_at")),
    invalid_at: parseDateValue(getRecordValue(record, "invalid_at")),
    confidence,
    epistemic_status: getRecordValue(record, "epistemic_status") ?? null,
    supported_by: getRecordValue(record, "supported_by") ?? null,
    supports: getRecordValue(record, "supports") ?? null,
    disputed_by: getRecordValue(record, "disputed_by") ?? null,
    epistemic_history: epistemicHistory,
    birth_score: birthScore,
    conditions,
    anchored_by: getRecordValue(record, "anchored_by") ?? null,
    anchors: getRecordValue(record, "anchors") ?? null,
    interpretations
  };
}
function resolveEntityEdgeOps(driver) {
  if (driver instanceof Neo4jDriver) {
    return driver.entityEdgeOps;
  }
  if (driver instanceof FalkorDriver) {
    return driver.entityEdgeOps;
  }
  return;
}
function resolveEpisodicEdgeOps(driver) {
  if (driver instanceof Neo4jDriver) {
    return driver.episodicEdgeOps;
  }
  if (driver instanceof FalkorDriver) {
    return driver.episodicEdgeOps;
  }
  return;
}

