// src/driver/falkordb/falkordb-saga-node-operations.ts
class FalkorSagaNodeOperations {
  async save(driver, node) {
    validateGroupId(node.group_id);
    await driver.executeQuery(`
        MERGE (n:Saga {uuid: $saga.uuid})
        SET n += $saga
        SET n:Saga
        RETURN n.uuid AS uuid
      `, { params: { saga: serializeForFalkor(node) } });
  }
  async saveBulk(driver, nodes) {
    if (nodes.length === 0)
      return;
    for (const node of nodes) {
      await this.save(driver, node);
    }
  }
  async getByUuid(driver, uuid) {
    const result = await driver.executeQuery(`
        MATCH (s:Saga {uuid: $uuid})
        RETURN
          s.uuid AS uuid,
          s.name AS name,
          s.group_id AS group_id,
          coalesce(s.labels, labels(s)) AS labels,
          s.created_at AS created_at,
          s.summary AS summary
      `, { params: { uuid }, routing: "r" });
    const record = result.records[0];
    if (!record) {
      throw new NodeNotFoundError(uuid);
    }
    return mapSagaNode2(record);
  }
  async getByUuids(driver, uuids) {
    if (uuids.length === 0)
      return [];
    const result = await driver.executeQuery(`
        MATCH (s:Saga)
        WHERE s.uuid IN $uuids
        RETURN
          s.uuid AS uuid,
          s.name AS name,
          s.group_id AS group_id,
          coalesce(s.labels, labels(s)) AS labels,
          s.created_at AS created_at,
          s.summary AS summary
      `, { params: { uuids }, routing: "r" });
    return result.records.map((record) => mapSagaNode2(record));
  }
  async getByGroupIds(driver, groupIds) {
    if (groupIds.length === 0)
      return [];
    const result = await driver.executeQuery(`
        MATCH (s:Saga)
        WHERE s.group_id IN $group_ids
        RETURN
          s.uuid AS uuid,
          s.name AS name,
          s.group_id AS group_id,
          coalesce(s.labels, labels(s)) AS labels,
          s.created_at AS created_at,
          s.summary AS summary
        ORDER BY s.uuid DESC
      `, { params: { group_ids: groupIds }, routing: "r" });
    return result.records.map((record) => mapSagaNode2(record));
  }
  async deleteByUuid(driver, uuid) {
    const result = await driver.executeQuery(`
        MATCH (n:Saga {uuid: $uuid})
        WITH collect(n) AS nodes
        FOREACH (node IN nodes | DETACH DELETE node)
        RETURN size(nodes) AS deleted_count
      `, { params: { uuid } });
    if ((result.records[0]?.deleted_count ?? 0) === 0) {
      throw new NodeNotFoundError(uuid);
    }
  }
  async deleteByUuids(driver, uuids) {
    if (uuids.length === 0)
      return;
    await driver.executeQuery(`
        MATCH (n:Saga)
        WHERE n.uuid IN $uuids
        WITH collect(n) AS nodes
        FOREACH (node IN nodes | DETACH DELETE node)
        RETURN size(nodes) AS deleted_count
      `, { params: { uuids } });
  }
  async deleteByGroupId(driver, groupId) {
    validateGroupId(groupId);
    await driver.executeQuery(`
        MATCH (n:Saga)
        WHERE n.group_id = $group_id
        WITH collect(n) AS nodes
        FOREACH (node IN nodes | DETACH DELETE node)
        RETURN size(nodes) AS deleted_count
      `, { params: { group_id: groupId } });
  }
}
function mapSagaNode2(record) {
  const rawLabels = getRecordValue(record, "labels") ?? [];
  return {
    uuid: getRecordValue(record, "uuid") ?? "",
    name: getRecordValue(record, "name") ?? "",
    group_id: getRecordValue(record, "group_id") ?? "",
    labels: rawLabels.filter((label) => label !== "Saga"),
    created_at: parseDateValue(getRecordValue(record, "created_at")) ?? new Date,
    summary: getRecordValue(record, "summary") ?? ""
  };
}

