function resolveSearchOps(driver) {
  if (driver instanceof Neo4jDriver) {
    return driver.searchOps;
  }
  if (driver instanceof FalkorDriver) {
    return driver.searchOps;
  }
  return;
}
function createFirstSeenMap(values, getKey) {
  const result = new Map;
  for (const value of values) {
    const key = getKey(value);
    if (!result.has(key)) {
      result.set(key, value);
    }
  }
  return result;
}
async function rerankWithCrossEncoder(query, candidates, crossEncoder, getPassage, getUuid, minScore, limit2) {
  if (candidates.length === 0) {
    return { items: [], scores: [] };
  }
  const buckets = new Map;
  for (const candidate of candidates) {
    const passage = getPassage(candidate);
    const existing = buckets.get(passage) ?? [];
    existing.push(candidate);
    buckets.set(passage, existing);
  }
  const ranked = await crossEncoder.rank(query, candidates.map((candidate) => getPassage(candidate)));
  const items = [];
  const scores = [];
  for (const [passage, score] of ranked) {
    if (score < minScore) {
      continue;
    }
    const bucket = buckets.get(passage);
    const candidate = bucket?.shift();
    if (!candidate) {
      continue;
    }
    items.push(candidate);
    scores.push(score);
    if (items.length >= limit2) {
      break;
    }
  }
  return { items, scores };
}
function buildNodePassage(node) {
  return `${node.name}
${node.summary}`.trim();
}
function buildEdgePassage(edge) {
  return `${edge.name}
${edge.fact}`.trim();
}
function buildEpisodePassage(episode) {
  return `${episode.name}
${episode.source_description}
${episode.content}`.trim();
}
function buildCommunityPassage(community) {
  return `${community.name}
${community.summary}`.trim();
}
async function collectCommunitySearchResults(ops, driver, query, groupIds, config, options, crossEncoder) {
  const communityConfig = config.community_config;
  if (!communityConfig) {
    return { communities: [], scores: [] };
  }
  const searchResults = [];
  const expandedLimit = config.limit * 2;
  const queryEmbedding = options.query_embedding ?? null;
  if (communityConfig.search_methods.includes(CommunitySearchMethods.cosine_similarity) && queryEmbedding && ops.communitySimilaritySearch) {
    searchResults.push(await ops.communitySimilaritySearch(driver, queryEmbedding, groupIds, expandedLimit, communityConfig.sim_min_score));
  }
  if (communityConfig.search_methods.includes(CommunitySearchMethods.bm25) && ops.communityFulltextSearch) {
    searchResults.push(await ops.communityFulltextSearch(driver, query, groupIds, expandedLimit));
  }
  if (searchResults.length === 0) {
    return { communities: [], scores: [] };
  }
  const uuidLists = searchResults.map((results) => results.map((c2) => c2.uuid));
  const communityMap = new Map;
  for (const results of searchResults) {
    for (const community of results) {
      if (!communityMap.has(community.uuid)) {
        communityMap.set(community.uuid, community);
      }
    }
  }
  const reranker = communityConfig.reranker;
  let rerankedUuids;
  let rerankedScores;
  switch (reranker) {
    case CommunityRerankers.rrf: {
      const rrf = reciprocalRankFusion(uuidLists, config.reranker_min_score);
      rerankedUuids = rrf.uuids;
      rerankedScores = rrf.scores;
      break;
    }
    case CommunityRerankers.mmr: {
      if (!queryEmbedding) {
        throw new SearchRerankerError("MMR reranker requires a query embedding");
      }
      const allCommunities = [...communityMap.values()];
      const mmr = maximalMarginalRelevance(allCommunities, queryEmbedding, (c2) => c2.name_embedding, (c2) => c2.uuid, communityConfig.mmr_lambda, config.reranker_min_score);
      rerankedUuids = mmr.items.map((c2) => c2.uuid);
      rerankedScores = mmr.scores;
      break;
    }
    case CommunityRerankers.cross_encoder: {
      if (!crossEncoder) {
        throw new SearchRerankerError("Cross-encoder reranker requires a cross-encoder client");
      }
      const passages = [...communityMap.values()].map((c2) => buildCommunityPassage(c2));
      const ranked = await crossEncoder.rank(query, passages);
      const passageToUuid = new Map;
      for (const c2 of communityMap.values()) {
        passageToUuid.set(buildCommunityPassage(c2), c2.uuid);
      }
      rerankedUuids = [];
      rerankedScores = [];
      for (const [passage, score] of ranked) {
        if (score >= config.reranker_min_score) {
          const uuid = passageToUuid.get(passage);
          if (uuid) {
            rerankedUuids.push(uuid);
            rerankedScores.push(score);
          }
        }
      }
      break;
    }
    default: {
      const rrf = reciprocalRankFusion(uuidLists, 0);
      rerankedUuids = rrf.uuids;
      rerankedScores = rrf.scores;
    }
  }
  const communities = rerankedUuids.slice(0, config.limit).map((uuid) => communityMap.get(uuid)).filter((c2) => c2 !== undefined);
  return {
    communities,
    scores: rerankedScores.slice(0, config.limit)
  };
}

// src/utils/concurrency.ts
async function semaphoreGather(tasks, maxConcurrency = 10) {
  if (tasks.length === 0)
    return [];
  const results = new Array(tasks.length);
  let nextIndex = 0;
  async function runNext() {
    while (nextIndex < tasks.length) {
      const currentIndex = nextIndex++;
      results[currentIndex] = await tasks[currentIndex]();
    }
  }
  const workers = Array.from({ length: Math.min(maxConcurrency, tasks.length) }, () => runNext());
  await Promise.all(workers);
  return results;
}

// src/utils/multi-group.ts
function needsMultiGroupRouting(driver, groupIds) {
  return driver.provider === GraphProviders.FALKORDB && Array.isArray(groupIds) && groupIds.length > 1;
}
async function executeWithMultiGroupRouting(driver, groupIds, fn, maxCoroutines) {
  if (!(driver instanceof FalkorDriver)) {
    return fn(driver, groupIds);
  }
  const results = await semaphoreGather(groupIds.map((gid) => async () => {
    const clonedDriver = driver.clone(gid);
    return fn(clonedDriver, [gid]);
  }), maxCoroutines ?? 10);
  return mergeResults(results);
}
function mergeResults(results) {
  if (results.length === 0) {
    return results;
  }
  const first = results[0];
  if (isSearchResults(first)) {
    return mergeSearchResults(results);
  }
  if (Array.isArray(first)) {
    const merged = [];
    for (const result of results) {
      merged.push(...result);
    }
    return merged;
  }
  if (first !== null && typeof first === "object" && "nodes" in first && "edges" in first) {
    const merged = {};
    for (const key of Object.keys(first)) {
      merged[key] = [];
    }
    for (const result of results) {
      for (const key of Object.keys(result)) {
        const val = result[key];
        if (Array.isArray(val)) {
          merged[key].push(...val);
        }
      }
    }
    return merged;
  }
  return results;
}
function isSearchResults(value) {
  if (value === null || typeof value !== "object")
    return false;
  const obj = value;
  return "edges" in obj && "nodes" in obj && "edge_reranker_scores" in obj && "node_reranker_scores" in obj;
}

// src/telemetry.ts
import { randomUUID as randomUUID2 } from "crypto";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "fs";
import { join } from "path";
import { homedir } from "os";
var POSTHOG_API_KEY = "phc_UG6EcfDbuXz92neb3rMlQFDY0csxgMqRcIPWESqnSmo";
var POSTHOG_HOST = "https://us.i.posthog.com";
var TELEMETRY_ENV_VAR = "GRAPHITI_TELEMETRY_ENABLED";
var cachedAnonymousId = null;
function isTelemetryEnabled() {
  try {
    const envValue = process.env[TELEMETRY_ENV_VAR]?.toLowerCase() ?? "true";
    return envValue === "true" || envValue === "1" || envValue === "yes" || envValue === "on";
  } catch {
    return false;
  }
}
function getAnonymousId() {
  if (cachedAnonymousId)
    return cachedAnonymousId;
  try {
    const cacheDir = join(homedir(), ".cache", "graphiti");
    const idFile = join(cacheDir, "telemetry_anon_id");
    if (existsSync(idFile)) {
      const id = readFileSync(idFile, "utf-8").trim();
      if (id) {
        cachedAnonymousId = id;
        return id;
      }
    }
    const newId = randomUUID2();
    try {
      mkdirSync(cacheDir, { recursive: true });
      writeFileSync(idFile, newId);
    } catch {}
    cachedAnonymousId = newId;
    return newId;
  } catch {
    return "UNKNOWN";
  }
}
function captureEvent(eventName, properties) {
  if (!isTelemetryEnabled())
    return;
  try {
    const userId = getAnonymousId();
    const eventProperties = {
      $process_person_profile: false,
      ...properties ?? {}
    };
    fetch(`${POSTHOG_HOST}/capture/`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        api_key: POSTHOG_API_KEY,
        event: eventName,
        distinct_id: userId,
        properties: eventProperties
      })
    }).catch(() => {});
  } catch {}
}

