// src/utils/text.ts
var MAX_SUMMARY_CHARS = 500;
var LUCENE_SPECIAL_CHARS = /[+\-&|!(){}[\]^"~*?:\\/]/g;
function luceneSanitize(query) {
  return query.replace(LUCENE_SPECIAL_CHARS, "\\$&");
}
function normalizeL2(embedding) {
  let sumSquared = 0;
  for (const value of embedding) {
    sumSquared += value * value;
  }
  const norm = Math.sqrt(sumSquared);
  if (norm === 0)
    return embedding;
  return embedding.map((value) => value / norm);
}
function buildFulltextQuery(query, groupIds, maxQueryLength = 8000) {
  let sanitized = luceneSanitize(query);
  if (sanitized.length > maxQueryLength) {
    sanitized = sanitized.slice(0, maxQueryLength);
  }
  return sanitized.trim();
}
function truncateAtSentence(text, maxChars) {
  if (text.length <= maxChars)
    return text;
  const truncated = text.slice(0, maxChars);
  let lastSentenceEnd = -1;
  for (let i2 = truncated.length - 1;i2 >= 0; i2--) {
    if (truncated[i2] === "." || truncated[i2] === "!" || truncated[i2] === "?") {
      lastSentenceEnd = i2;
      break;
    }
  }
  if (lastSentenceEnd > 0) {
    return truncated.slice(0, lastSentenceEnd + 1).trimEnd();
  }
  return truncated.trimEnd();
}

// src/maintenance/node-operations.ts
var MAX_NODES = 30;
function buildContext(clients) {
  return {
    tokenTracker: clients.tokenTracker ?? null,
    cache: clients.cache ?? null
  };
}
async function callGenerateResponse(client, messages, options, context) {
  if (client.generateResponse) {
    return client.generateResponse(messages, options, context);
  }
  return generateResponse(client, messages, options, context);
}
function buildEntityTypesContext(entityTypes) {
  const context = [
    {
      entity_type_id: 0,
      entity_type_name: "Entity",
      entity_type_description: "Default entity classification. Use this entity type if the entity is not one of the other listed types."
    }
  ];
  if (entityTypes) {
    let id = 1;
    for (const [typeName, typeDef] of Object.entries(entityTypes)) {
      context.push({
        entity_type_id: id++,
        entity_type_name: typeName,
        entity_type_description: typeDef.description ?? `Entity type: ${typeName}`
      });
    }
  }
  return context;
}
async function extractNodes(clients, episode, previousEpisodes, entityTypes, excludedEntityTypes, customExtractionInstructions) {
  const llmClient = clients.llm_client;
  const entityTypesContext = buildEntityTypesContext(entityTypes);
  const context = {
    episode_content: episode.content,
    episode_timestamp: (episode.valid_at ?? episode.created_at).toISOString(),
    previous_episodes: previousEpisodes.map((ep) => ep.content),
    custom_extraction_instructions: customExtractionInstructions ?? "",
    entity_types: JSON.stringify(entityTypesContext, null, 2),
    source_description: episode.source_description,
    current_message: episode.content,
    previous_messages: previousEpisodes.map((ep) => ep.content).join(`
`),
    content: episode.content
  };
  let prompt;
  let promptName;
  if (episode.source === EpisodeTypes.message) {
    prompt = promptLibrary.extractNodes.extractMessage(context);
    promptName = "extract_nodes.extract_message";
  } else if (episode.source === EpisodeTypes.json) {
    prompt = promptLibrary.extractNodes.extractJson(context);
    promptName = "extract_nodes.extract_json";
  } else {
    prompt = promptLibrary.extractNodes.extractText(context);
    promptName = "extract_nodes.extract_text";
  }
  const llmResponse = await callGenerateResponse(llmClient, prompt, {
    response_model: { type: "object", properties: { extracted_entities: { type: "array" } } },
    group_id: episode.group_id,
    prompt_name: promptName
  }, buildContext(clients));
  const extractedEntities = llmResponse.extracted_entities ?? [];
  const filteredEntities = extractedEntities.filter((e2) => e2.name && e2.name.trim() !== "");
  return createEntityNodes(filteredEntities, entityTypesContext, excludedEntityTypes, episode);
}
function createEntityNodes(extractedEntities, entityTypesContext, excludedEntityTypes, episode) {
  const nodes = [];
  const now = utcNow();
  for (const extracted of extractedEntities) {
    const typeId = extracted.entity_type_id;
    let entityTypeName = "Entity";
    if (typeId >= 0 && typeId < entityTypesContext.length) {
      entityTypeName = entityTypesContext[typeId]?.entity_type_name ?? "Entity";
    }
    if (excludedEntityTypes?.includes(entityTypeName)) {
      continue;
    }
    const labels = [...new Set(["Entity", entityTypeName])];
    nodes.push({
      uuid: crypto.randomUUID(),
      name: extracted.name,
      group_id: episode.group_id,
      labels,
      summary: "",
      created_at: now
    });
  }
  return nodes;
}
async function resolveExtractedNodes(clients, extractedNodes, episode, previousEpisodes, entityTypes, existingNodesOverride) {
  if (extractedNodes.length === 0) {
    return [[], {}, []];
  }
  const llmClient = clients.llm_client;
  const existingNodes = await collectCandidateNodes(clients, extractedNodes, existingNodesOverride ?? null);
  const indexes = buildCandidateIndexes(existingNodes);
  const state = {
    resolvedNodes: new Array(extractedNodes.length).fill(null),
    uuidMap: new Map,
    unresolvedIndices: [],
    duplicatePairs: []
  };
  resolveWithSimilarity(extractedNodes, indexes, state);
  await resolveWithLlm(llmClient, extractedNodes, indexes, state, episode ?? null, previousEpisodes ?? null, entityTypes ?? null, buildContext(clients));
  for (let idx = 0;idx < extractedNodes.length; idx++) {
    if (state.resolvedNodes[idx] === null) {
      state.resolvedNodes[idx] = extractedNodes[idx];
      state.uuidMap.set(extractedNodes[idx].uuid, extractedNodes[idx].uuid);
    }
  }
  const resolvedNodes = state.resolvedNodes.filter((n2) => n2 !== null);
  const uuidMap = Object.fromEntries(state.uuidMap);
  const duplicatePairs = state.duplicatePairs;
  return [resolvedNodes, uuidMap, duplicatePairs];
}
async function collectCandidateNodes(clients, extractedNodes, existingNodesOverride) {
  const searchResults = await semaphoreGather(extractedNodes.map((node) => () => search(clients.driver, node.name, [node.group_id], NODE_HYBRID_SEARCH_RRF, createSearchFilters())));
  const candidateNodes = searchResults.flatMap((result) => result.nodes);
  if (existingNodesOverride) {
    candidateNodes.push(...existingNodesOverride);
  }
  const seen = new Set;
  return candidateNodes.filter((node) => {
    if (seen.has(node.uuid))
      return false;
    seen.add(node.uuid);
    return true;
  });
}
async function resolveWithLlm(llmClient, extractedNodes, indexes, state, episode, previousEpisodes, entityTypes, llmContext) {
  if (state.unresolvedIndices.length === 0)
    return;
  const llmExtractedNodes = state.unresolvedIndices.map((i2) => extractedNodes[i2]);
  const extractedNodesContext = llmExtractedNodes.map((node, i2) => ({
    id: i2,
    name: node.name,
    entity_type: node.labels,
    entity_type_description: entityTypes?.[node.labels.find((l2) => l2 !== "Entity") ?? ""]?.description ?? "Default Entity Type"
  }));
  const existingNodesContext = indexes.existingNodes.map((candidate) => ({
    name: candidate.name,
    entity_types: candidate.labels,
    ...candidate.attributes ?? {}
  }));
  const existingNodesByName = new Map;
  for (const node of indexes.existingNodes) {
    existingNodesByName.set(node.name, node);
  }
  const context = {
    entities: JSON.stringify(extractedNodesContext),
    existing_entities: JSON.stringify(existingNodesContext),
    current_message: episode?.content ?? "",
    previous_messages: previousEpisodes?.map((ep) => ep.content).join(`
`) ?? ""
  };
  const llmResponse = await callGenerateResponse(llmClient, promptLibrary.dedupeNodes.dedupeNodes(context), {
    response_model: {
      type: "object",
      properties: { entity_resolutions: { type: "array" } }
    },
    prompt_name: "dedupe_nodes.nodes"
  }, llmContext);
  const nodeResolutions = llmResponse.entity_resolutions ?? [];
  const processedRelativeIds = new Set;
  for (const resolution of nodeResolutions) {
    const relativeId = resolution.id;
    const duplicateName = resolution.duplicate_name;
    if (relativeId < 0 || relativeId >= state.unresolvedIndices.length)
      continue;
    if (processedRelativeIds.has(relativeId))
      continue;
    processedRelativeIds.add(relativeId);
    const originalIndex = state.unresolvedIndices[relativeId];
    const extractedNode = extractedNodes[originalIndex];
    let resolvedNode;
    if (!duplicateName) {
      resolvedNode = extractedNode;
    } else if (existingNodesByName.has(duplicateName)) {
      resolvedNode = existingNodesByName.get(duplicateName);
    } else {
      resolvedNode = extractedNode;
    }
    state.resolvedNodes[originalIndex] = resolvedNode;
    state.uuidMap.set(extractedNode.uuid, resolvedNode.uuid);
    if (resolvedNode.uuid !== extractedNode.uuid) {
      state.duplicatePairs.push([extractedNode, resolvedNode]);
    }
  }
}
async function extractAttributesFromNodes(clients, nodes, episode, previousEpisodes, entityTypes, edges) {
  const llmClient = clients.llm_client;
  const embedder = clients.embedder;
  const edgesByNode = new Map;
  if (edges) {
    for (const edge of edges) {
      if (!edgesByNode.has(edge.source_node_uuid)) {
        edgesByNode.set(edge.source_node_uuid, []);
      }
      if (!edgesByNode.has(edge.target_node_uuid)) {
        edgesByNode.set(edge.target_node_uuid, []);
      }
      edgesByNode.get(edge.source_node_uuid).push(edge);
      edgesByNode.get(edge.target_node_uuid).push(edge);
    }
  }
  const ctx = buildContext(clients);
  const attributeResults = await semaphoreGather(nodes.map((node) => () => extractEntityAttributes(llmClient, node, episode ?? null, previousEpisodes ?? null, entityTypes?.[node.labels.find((l2) => l2 !== "Entity") ?? ""] ?? null, ctx)));
  for (let i2 = 0;i2 < nodes.length; i2++) {
    const node = nodes[i2];
    const attrs = attributeResults[i2];
    if (attrs && Object.keys(attrs).length > 0) {
      node.attributes = { ...node.attributes ?? {}, ...attrs };
    }
  }
  await extractEntitySummariesBatch(llmClient, nodes, episode ?? null, previousEpisodes ?? null, edgesByNode, ctx);
  if (embedder) {
    await semaphoreGather(nodes.filter((node) => !node.name_embedding).map((node) => async () => {
      node.name_embedding = await embedder.create([node.name.replaceAll(`
`, " ")]);
    }));
  }
  return nodes;
}
async function extractEntityAttributes(llmClient, node, episode, previousEpisodes, entityType, llmContext) {
  if (!entityType || !entityType.fields || Object.keys(entityType.fields).length === 0) {
    return {};
  }
  const context = {
    node: {
      name: node.name,
      entity_types: node.labels,
      attributes: node.attributes ?? {}
    },
    episode_content: episode?.content ?? "",
    previous_episodes: previousEpisodes?.map((ep) => ep.content) ?? []
  };
  const llmResponse = await callGenerateResponse(llmClient, promptLibrary.extractNodes.extractAttributes(context), {
    response_model: entityType.fields,
    model_size: "small",
    group_id: node.group_id,
    prompt_name: "extract_nodes.extract_attributes"
  }, llmContext);
  return llmResponse;
}
async function extractEntitySummariesBatch(llmClient, nodes, episode, previousEpisodes, edgesByNode, llmContext) {
  const nodesNeedingLlm = [];
  for (const node of nodes) {
    const nodeEdges = edgesByNode.get(node.uuid) ?? [];
    let summaryWithEdges = node.summary;
    if (nodeEdges.length > 0) {
      const edgeFacts = nodeEdges.map((e2) => e2.fact).filter(Boolean).join(`
`);
      summaryWithEdges = `${summaryWithEdges}
${edgeFacts}`.trim();
    }
    if (summaryWithEdges && summaryWithEdges.length <= MAX_SUMMARY_CHARS * 4) {
      node.summary = summaryWithEdges;
      continue;
    }
    if (!summaryWithEdges && !episode)
      continue;
    nodesNeedingLlm.push(node);
  }
  if (nodesNeedingLlm.length === 0)
    return;
  const flights = [];
  for (let i2 = 0;i2 < nodesNeedingLlm.length; i2 += MAX_NODES) {
    flights.push(nodesNeedingLlm.slice(i2, i2 + MAX_NODES));
  }
  await semaphoreGather(flights.map((flight) => () => processSummaryFlight(llmClient, flight, episode, previousEpisodes, llmContext)));
}
async function processSummaryFlight(llmClient, nodes, episode, previousEpisodes, llmContext) {
  const entitiesContext = nodes.map((node) => ({
    name: node.name,
    summary: node.summary,
    entity_types: node.labels,
    attributes: node.attributes ?? {}
  }));
  const batchContext = {
    entities: JSON.stringify(entitiesContext),
    episode_content: episode?.content ?? "",
    previous_episodes: previousEpisodes?.map((ep) => ep.content) ?? []
  };
  const groupId = nodes[0]?.group_id ?? null;
  const llmResponse = await callGenerateResponse(llmClient, promptLibrary.extractNodes.extractSummariesBatch(batchContext), {
    response_model: { type: "object", properties: { summaries: { type: "array" } } },
    model_size: "small",
    group_id: groupId,
    prompt_name: "extract_nodes.extract_summaries_batch"
  }, llmContext);
  const nameToNodes = new Map;
  for (const node of nodes) {
    const key = node.name.toLowerCase();
    if (!nameToNodes.has(key))
      nameToNodes.set(key, []);
    nameToNodes.get(key).push(node);
  }
  const summariesResponse = llmResponse;
  if (summariesResponse.summaries) {
    for (const summarized of summariesResponse.summaries) {
      const matchingNodes = nameToNodes.get(summarized.name.toLowerCase());
      if (matchingNodes) {
        const truncatedSummary = truncateAtSentence(summarized.summary, MAX_SUMMARY_CHARS);
        for (const node of matchingNodes) {
          node.summary = truncatedSummary;
        }
      }
    }
  }
}

// src/maintenance/negation.ts
var HIGH_CONFIDENCE_NEGATION = [
  /\bno longer\b/i,
  /\bstopped using\b/i,
  /\bdeprecated\b/i,
  /\bremoved\b/i,
  /\bdropped\b/i,
  /\bdecommissioned\b/i,
  /\breplaced\b(?:\s+\w+)?\s+(?:by|with)\b/i,
  /\bmigrated (?:from|away)\b/i,
  /\bswitched (?:from|away)\b/i,
  /\beliminated\b/i,
  /\bdiscontinued\b/i,
  /\bno longer (?:uses?|supports?|requires?|needs?)\b/i
];
var MEDIUM_CONFIDENCE_NEGATION = [
  /\binstead of\b/i,
  /\brather than\b/i,
  /\bused to\b/i,
  /\bpreviously\b/i,
  /\bformerly\b/i,
  /\bwas\b.*\bnow\b/i,
  /\bchanged (?:from|to)\b/i,
  /\bupdated (?:from|to)\b/i
];
function detectNegation(newFact, existingFact, sharedEntities) {
  for (const pattern of HIGH_CONFIDENCE_NEGATION) {
    if (pattern.test(newFact)) {
      if (sharedEntities.length > 0) {
        return { confidence: "high", pattern: pattern.source };
      }
      return { confidence: "medium", pattern: pattern.source };
    }
  }
  for (const pattern of MEDIUM_CONFIDENCE_NEGATION) {
    if (pattern.test(newFact)) {
      return { confidence: "medium", pattern: pattern.source };
    }
  }
  return { confidence: "none", pattern: "" };
}

