var DEFAULT_MODEL9 = "gemini-2.5-flash-lite";

class GeminiRerankerClient {
  generativeModel;
  modelName;
  constructor(options = {}) {
    const config = createLLMConfig(options.config);
    this.modelName = config.model ?? DEFAULT_MODEL9;
    if (options.model) {
      this.generativeModel = options.model;
    } else {
      const apiKey = config.api_key ?? process.env.GOOGLE_API_KEY ?? "";
      const genAI = new GoogleGenerativeAI(apiKey);
      this.generativeModel = genAI.getGenerativeModel({
        model: this.modelName,
        generationConfig: {
          temperature: 0,
          maxOutputTokens: 3
        },
        systemInstruction: "You are an expert at rating passage relevance. Respond with only a number from 0-100."
      });
    }
  }
  async rank(query, passages) {
    if (passages.length <= 1) {
      return passages.map((p2) => [p2, 1]);
    }
    try {
      const results = await Promise.all(passages.map((passage) => this.scorePassage(query, passage)));
      return results.sort((a2, b2) => b2[1] - a2[1]);
    } catch (error2) {
      if (isRateLimitError2(error2)) {
        throw new RateLimitError2(String(error2));
      }
      throw error2;
    }
  }
  async scorePassage(query, passage) {
    const prompt = `Rate how well this passage answers or relates to the query. Use a scale from 0 to 100.

Query: ${query}

Passage: ${passage}

Provide only a number between 0 and 100 (no explanation, just the number):`;
    try {
      const result = await this.generativeModel.generateContent({
        contents: [{ role: "user", parts: [{ text: prompt }] }]
      });
      const text = result.response.text().trim();
      const match = text.match(/\b(\d{1,3})\b/);
      if (match) {
        const score = Number(match[1]);
        return [passage, Math.max(0, Math.min(1, score / 100))];
      }
      return [passage, 0];
    } catch (error2) {
      if (isRateLimitError2(error2))
        throw error2;
      return [passage, 0];
    }
  }
}
function isRateLimitError2(error2) {
  if (error2 instanceof RateLimitError2)
    return true;
  if (error2 instanceof Error) {
    const msg = error2.message.toLowerCase();
    return msg.includes("429") || msg.includes("rate limit") || msg.includes("quota") || msg.includes("resource_exhausted");
  }
  return false;
}
